class Campaign:
    def __init__(self, name, budget):
        self.name = name
        self.budget = budget
    def cost(self):
        return self.budget

class EmailCampaign(Campaign):
    def __init__(self, name, budget, sends):
        super().__init__(name, budget)
        self.sends = sends
    def cost(self):
        return super().cost() + self.sends * 0.01

print(EmailCampaign("Promo", 100, 2000).cost())

